const evaluationFields = ["complexite_technique", "difficulte_terrain", "risque_sous_dimensionnement"];
const controlChildren = ['champs_non_trouves', 'incoherences', 'a_verifier'];

let successReady = true;
let errorStage = null;
let errorCode = null;
let errorMessage = null;
let missingElement = null;

const hasOpeningTag = (name) => new RegExp(`<${name}(?:\\s|>)`, 'i').test(xml);
const hasClosingTag = (name) => new RegExp(`</${name}>`, 'i').test(xml);
const hasAttributeOnOpeningTag = (name, attribute) =>
  new RegExp(`<${name}\\b[^>]*\\b${attribute}=`, 'i').test(xml);
const sectionBody = (name) => {
  const match = xml.match(new RegExp(`<${name}\\b[^>]*>([\\s\\S]*?)</${name}>`, 'i'));
  return match ? match[1] : null;
};
const fail = (code, message, element = null) => {
  successReady = false;
  errorStage = 'XML';
  errorCode = code;
  errorMessage = message;
  missingElement = element;
};

if (!markdown) {
  fail('MARKDOWN_EMPTY', 'Le markdown retourne par Marker est vide.');
} else if (!xml) {
  fail('XML_EMPTY', 'Le XML retourne par Gemini est vide.');
} else if (!hasOpeningTag('fiche_projet')) {
  fail('XML_INVALID_ROOT', 'Le XML retourne par Gemini ne contient pas la racine fiche_projet attendue.', 'fiche_projet');
} else if (!hasClosingTag('fiche_projet')) {
  fail('XML_INCOMPLETE', 'Le XML retourne par Gemini est incomplet : balise fermante </fiche_projet> manquante.', 'fiche_projet');
} else if (!hasOpeningTag('reference_interne') || !hasClosingTag('reference_interne')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas l\'element obligatoire <reference_interne>.', 'reference_interne');
} else if (!hasOpeningTag('extraction') || !hasClosingTag('extraction')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas la section obligatoire <extraction>.', 'extraction');
} else if (!hasOpeningTag('evaluation') || !hasClosingTag('evaluation')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas la section obligatoire <evaluation>.', 'evaluation');
} else if (!hasOpeningTag('controle') || !hasClosingTag('controle')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas la section obligatoire <controle>.', 'controle');
}

if (successReady) {
  for (const field of extractionFields) {
    if (!hasOpeningTag(field)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element obligatoire <${field}>.`, field);
      break;
    }
    if (!hasClosingTag(field)) {
      fail('XML_INCOMPLETE', `Le XML retourne par Gemini est incomplet : balise fermante </${field}> manquante.`, field);
      break;
    }
    if (!hasAttributeOnOpeningTag(field, 'source')) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'attribut source obligatoire sur <${field}>.`, field);
      break;
    }
  }
}

if (successReady) {
  for (const field of evaluationFields) {
    if (!hasOpeningTag(field)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element d'evaluation obligatoire <${field}>.`, field);
      break;
    }
    if (!hasClosingTag(field)) {
      fail('XML_INCOMPLETE', `Le XML retourne par Gemini est incomplet : balise fermante </${field}> manquante.`, field);
      break;
    }
    if (!hasAttributeOnOpeningTag(field, 'note')) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'attribut note obligatoire sur <${field}>.`, field);
      break;
    }

    const evaluationBody = sectionBody(field);
    if (!evaluationBody) {
      fail('XML_INCOMPLETE', `Le XML retourne par Gemini est incomplet : contenu de <${field}> indisponible.`, field);
      break;
    }
    if (!/<justification(?:\s|>)/i.test(evaluationBody) || !/<\/justification>/i.test(evaluationBody)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element <justification> obligatoire dans <${field}>.`, field);
      break;
    }
    if (field === 'risque_sous_dimensionnement' &&
